&lt;p style=&quot;color: !important;&quot;&gt;&lt;span style=&quot;color: rgb(31, 56, 100); font-size: 12pt;&quot;&gt;&lt;strong&gt;Desired qualifications&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
